const LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
  [0, 3, 6], [1, 4, 7], [2, 5, 8], // columns
  [0, 4, 8], [2, 4, 6],            // diagonals
];

type Mark = 'X' | 'O' | null;

export function judge(cells: Mark[]): 'X' | 'O' | 'draw' | null {
  for (const [a, b, c] of LINES) {
    if (cells[a] && cells[a] === cells[b] && cells[a] === cells[c]) {
      return cells[a]; // we have a winner
    }
  }
  return cells.every(Boolean) ? 'draw' : null;
}

// Reused from the OVO pipeline's core/board-ai module: the rebuilt Tic-Tac-Toe
// calls it directly, with zero changes to the rules.
function minimax(cells: Mark[], depth: number, isMaximizing: boolean): number {
  if (checkWinner(cells, aiPlayer)) return 10 - depth;     // AI wins: faster = higher score
  if (checkWinner(cells, humanPlayer)) return depth - 10;  // Opponent wins: slower = smaller loss
  const empty = getEmptyCells(cells);
  if (empty.length === 0) return 0;                        // Draw

  let best = isMaximizing ? -Infinity : Infinity;
  for (const e of empty) {
    cells[e.index] = isMaximizing ? aiPlayer : humanPlayer; // Try the move
    const score = minimax(cells, depth + 1, !isMaximizing);
    cells[e.index] = null;                                  // Backtrack
    best = isMaximizing ? Math.max(best, score) : Math.min(best, score);
  }
  return best;
}
